import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine watermark high_ts
    high_ts = watermark["high_ts"].iloc[0]

    # Keep only events strictly after the watermark
    events = events[events["event_ts"] > high_ts].copy()

    # Process events per user, sequentially, ordered by (event_ts, event_seq)
    events = events.sort_values(["user_id", "event_ts", "event_seq"], kind="mergesort")

    # Build initial state dict from target_snapshot
    state = {}
    for _, row in target.iterrows():
        state[row["user_id"]] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"],
        }

    seven_days = pd.Timedelta(days=7)

    for _, ev in events.iterrows():
        uid = ev["user_id"]
        op = ev["op"]
        ts = ev["event_ts"]
        email = ev["email"]

        cur = state.get(uid)

        if op == "D":
            # Soft delete: status becomes DELETED, status_ts updated,
            # email preserved as of deletion (existing email if present,
            # otherwise fall back to the event's email for a brand-new user).
            if cur is None:
                state[uid] = {
                    "email": email,
                    "status": "DELETED",
                    "status_ts": ts,
                }
            else:
                state[uid] = {
                    "email": cur["email"],
                    "status": "DELETED",
                    "status_ts": ts,
                }
        elif op == "U":
            if cur is None or cur["status"] == "ACTIVE":
                # New user or active user: straightforward upsert
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            elif cur["status"] == "DELETED":
                # Resurrection only if strictly more than 7 days after
                # the deletion's status_ts; otherwise discard.
                if ts > (cur["status_ts"] + seven_days):
                    state[uid] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                else:
                    # discard update, state unchanged
                    pass
            else:
                # Any unexpected status: treat like active upsert fallback
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }

    # Build output dataframe
    if state:
        out_rows = [
            {
                "user_id": uid,
                "email": s["email"],
                "status": s["status"],
                "status_ts": s["status_ts"],
            }
            for uid, s in state.items()
        ]
        new_snapshot = pd.DataFrame(
            out_rows, columns=["user_id", "email", "status", "status_ts"]
        )
        new_snapshot = new_snapshot.sort_values("user_id").reset_index(drop=True)
    else:
        new_snapshot = pd.DataFrame(
            columns=["user_id", "email", "status", "status_ts"]
        )

    return {"new_snapshot": new_snapshot}
